import React from 'react';
import { Users, Search } from 'lucide-react';

const CitizensTab = () => (
  <div className="w-full h-full bg-[#AB1717] border-[8px] border-[#47510B] rounded-[50px] p-8 red-stack-shadow flex flex-col gap-6">
    <div className="flex justify-between items-center bg-white border-4 border-[#47510B] p-4 rounded-2xl">
      <h3 className="font-black italic text-[#47510B]">CITIZEN_REGISTRY</h3>
      <Search className="text-[#AB1717]" />
    </div>
    <div className="flex-grow grid grid-cols-1 md:grid-cols-2 gap-4 overflow-y-auto">
      {[1, 2, 3, 4].map(i => (
        <div key={i} className="bg-[#FDFAD8] border-4 border-[#47510B] p-5 rounded-2xl flex items-center gap-4">
          <div className="w-12 h-12 bg-[#CAD23C] rounded-full border-2 border-[#47510B]" />
          <div>
            <p className="font-black text-sm text-[#47510B]">USER_NODE_0{i}</p>
            <p className="text-[10px] font-bold text-[#AB1717]">PREMIUM_ACCESS</p>
          </div>
        </div>
      ))}
    </div>
  </div>
);

export default CitizensTab;
